//! PCA 0.4.2 Intent Layer v2, rule 13 in the guest (`intent_session` module) against the TypeScript reference.
//!
//! `fixtures/ts_v2_session.json` (generated by `gen_ts_v2_session.ts` from packages/pca/src): the `intent_session` wire
//! rules, the session grant caveat, the session root S (shape, signature under the verifier's `pq_pins`, digest), the revocation ids, sorted-Merkle
//! non-membership, `checkSessionRevocation` (single revocation authority, full revoked list, append-only `last`; the
//! `rev13-*` scenarios) and the whole `intent_session`
//! check (`sessionStep` through `decideIntentV2`, incl. the conformance `session-*` scenarios).
//!
//! Verdicts must be equal. Reasons must be equal too, except where the TS message embeds a canonicalizer error text (the
//! prefix up to `canonicalize` must match). Cases with `requires_suite`: when the guest implements the suite
//! (`pq_suites::suite_supported`) the verdict and reason must match exactly; otherwise the guest must fail with a reason
//! containing `unsupported_suite` (README "suite capability"). Step cases whose context is malformed at the TOP level
//! (`ctx_error`) belong to the pipeline (`intentV2ContextError`, intent_v2.rs) and are not run through `session_step`.
use pca_zkvm_core::intent_session::*;
use pca_zkvm_core::pq_suites::suite_supported;
use serde_json::Value;

/// `Some(true)`: the guest implements the case's suite (compare exactly); `Some(false)`: it must refuse with
/// `unsupported_suite`; `None`: no suite requirement.
fn suite_case(c: &Value) -> Option<bool> {
    c.get("requires_suite").and_then(|a| a.as_str()).map(|a| suite_supported(Some(a)))
}

fn unsupported_ok(r: &Result<(), String>) -> bool {
    matches!(r, Err(e) if e.contains("unsupported_suite"))
}

fn fx() -> Value {
    let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../fixtures/ts_v2_session.json");
    serde_json::from_str(&std::fs::read_to_string(p).expect("fixture")).expect("fixture json")
}

fn reason_eq(ts: Option<&str>, rs: Option<&str>) -> bool {
    match (ts, rs) {
        (None, None) => true,
        (Some(a), Some(b)) if a == b => true,
        (Some(a), Some(b)) => match (a.find("canonicalize"), b.find("canonicalize")) {
            (Some(i), Some(j)) => a[..i] == b[..j],
            _ => false,
        },
        _ => false,
    }
}

fn s(v: &Value, k: &str) -> Option<String> {
    v.get(k).and_then(|x| x.as_str()).map(String::from)
}

fn report(what: &str, bad: &[String], n: usize) {
    if !bad.is_empty() {
        panic!("{what}: {} of {n} cases differ from the TS reference:\n{}", bad.len(), bad.join("\n"));
    }
}

#[test]
fn wire_matches_reference() {
    let d = fx();
    let cases = d["wire"].as_array().unwrap();
    assert!(cases.len() >= 60);
    let mut bad = Vec::new();
    for c in cases {
        let r = validate_intent_session_wire(&c["v"]);
        let ok = c["ok"].as_bool().unwrap();
        if r.is_ok() != ok || !reason_eq(c["reason"].as_str(), r.as_ref().err().map(|x| x.as_str())) {
            bad.push(format!("{}: ts {:?} rust {:?}", c["name"], c["reason"], r));
        }
    }
    report("wire", &bad, cases.len());
}

#[test]
fn caveat_matches_reference() {
    let d = fx();
    let cases = d["caveat"].as_array().unwrap();
    let mut bad = Vec::new();
    for c in cases {
        let arg = if c["absent"].as_bool() == Some(true) { None } else { Some(&c["c"]) };
        let r = intent_session_caveat_error(arg);
        if !reason_eq(c["reason"].as_str(), r.as_deref()) {
            bad.push(format!("{}: ts {:?} rust {:?}", c["name"], c["reason"], r));
        }
    }
    report("caveat", &bad, cases.len());
    let cases = d["grant_caveat"].as_array().unwrap();
    let mut bad = Vec::new();
    for c in cases {
        let found = grant_session_caveat(&c["grant"]).cloned().unwrap_or(Value::Null);
        if found != c["found"] {
            bad.push(format!("{}: ts {} rust {}", c["name"], c["found"], found));
        }
    }
    report("grant_caveat", &bad, cases.len());
}

#[test]
fn session_roots_match_reference() {
    let d = fx();
    let cases = d["roots"].as_array().unwrap();
    assert!(cases.len() >= 150);
    let mut bad = Vec::new();
    let (mut pq, mut lacking, mut verified) = (0, 0, 0);
    for c in cases {
        let name = &c["name"];
        // `pq_pins`: the verifier's session-root PQ pins (R3-01, guest version 9); absent = none
        let v = verify_session_root_pinned(&c["s"], c.get("pq_pins"));
        let ts_ok = c["verify_ok"].as_bool().unwrap();
        match suite_case(c) {
            Some(false) => {
                lacking += 1;
                if !unsupported_ok(&v) {
                    bad.push(format!("{name}: a suite the guest lacks must fail with unsupported_suite, got {v:?}"));
                }
                continue;
            }
            Some(true) => pq += 1,
            None => {}
        }
        let shape = session_root_shape_error(&c["s"]);
        if !reason_eq(c["shape"].as_str(), shape.as_deref()) {
            bad.push(format!("{name}: shape ts {:?} rust {:?}", c["shape"], shape));
        }
        if v.is_ok() != ts_ok || !reason_eq(c["verify_reason"].as_str(), v.as_ref().err().map(|x| x.as_str())) {
            bad.push(format!("{name}: verify ts {:?} rust {:?}", c["verify_reason"], v));
        }
        if ts_ok {
            verified += 1;
            let dg = session_root_digest(&c["s"]);
            if dg != s(c, "digest") {
                bad.push(format!("{name}: digest ts {:?} rust {:?}", c["digest"], dg));
            }
        }
    }
    report("roots", &bad, cases.len());
    assert!(pq >= 8 && lacking >= 2 && verified >= 20, "pq {pq} lacking {lacking} verified {verified}");
}

#[test]
fn revocation_ids_match_reference() {
    let d = fx();
    let i = &d["ids"];
    assert_eq!(session_revocation_id(i["session"][0].as_str().unwrap()), i["session"][1]);
    assert_eq!(map_revocation_id(i["map"][0].as_str().unwrap()), i["map"][1]);
    assert_eq!(delta_revocation_id(i["delta"][0].as_str().unwrap()), i["delta"][1]);
    assert_eq!(profile_revocation_id(i["profile"][0].as_str().unwrap(), i["profile"][1].as_i64().unwrap()), i["profile"][2]);
    assert_eq!(session_revocation_scope(i["scope"][0].as_str().unwrap()), i["scope"][1]);
}

#[test]
fn non_membership_matches_reference() {
    let d = fx();
    let cases = d["nonmem"].as_array().unwrap();
    assert!(cases.len() >= 100);
    let mut bad = Vec::new();
    let mut oks = 0;
    for c in cases {
        let r = verify_non_membership(c.get("root"), c.get("proof"), c["id"].as_str().unwrap());
        let ts = c["ok"].as_bool().unwrap();
        oks += ts as usize;
        if r != ts {
            bad.push(format!("{}: ts {ts} rust {r}", c["name"]));
        }
    }
    assert!(oks >= 60);
    report("nonmem", &bad, cases.len());
}

#[test]
fn session_revocation_matches_reference() {
    let d = fx();
    let cases = d["revocation"].as_array().unwrap();
    assert!(cases.iter().filter(|c| c["name"].as_str().unwrap().starts_with("rev13-")).count() == 10 && cases.len() >= 85);
    let mut bad = Vec::new();
    for c in cases {
        let input = &c["input"];
        let r = if c["ev_absent"].as_bool() == Some(true) || c.get("ev_raw").is_some() {
            let ids = input.get("ids").and_then(|v| v.as_array()).map(|a| a.as_slice());
            let authority = input.get("authority").and_then(|v| v.as_str());
            check_session_revocation_full(c.get("ev_raw"), input["session"].as_str().unwrap(), None, authority, ids, input["now"].as_f64().unwrap(), input["max_age_ms"].as_f64().unwrap(), None, input.get("last"))
        } else {
            check_session_revocation_input(input)
        };
        let ts = c["ok"].as_bool().unwrap();
        if suite_case(c) == Some(false) {
            if !unsupported_ok(&r) {
                bad.push(format!("{}: a suite the guest lacks must fail with unsupported_suite, got {r:?}", c["name"]));
            }
            continue;
        }
        if r.is_ok() != ts || !reason_eq(c["reason"].as_str(), r.as_ref().err().map(|x| x.as_str())) {
            bad.push(format!("{}: ts {:?} rust {:?}", c["name"], c["reason"], r));
        }
    }
    report("revocation", &bad, cases.len());
}

const BOUND_ROOT_REASONS: [&str; 4] = [
    "no session root for this session",
    "intent_session.root is not the digest of the session root",
    "the session root names another session",
    "the session root has expired",
];

#[test]
fn session_step_matches_reference() {
    let d = fx();
    let cases = d["steps"].as_array().unwrap();
    assert!(cases.len() >= 80);
    let mut bad = Vec::new();
    let (mut reported, mut allowed, mut pq, mut lacking, mut pipeline) = (0, 0, 0, 0, 0);
    for c in cases {
        let name = &c["name"];
        if c["reported"].as_bool() != Some(true) {
            continue; // the check is not reported (no intent_session, no session.require): nothing to compare
        }
        if !c["ctx_error"].is_null() {
            pipeline += 1;
            continue; // a malformed top-level context: decideIntentV2 fails every check before sessionStep runs
        }
        reported += 1;
        let ctx = if c["ctx_absent"].as_bool() == Some(true) { None } else { Some(&c["ctx"]) };
        let now = c["now"].as_f64().unwrap();
        let r = session_step(&c["pcactn"], &c["grant"], ctx, now);
        match suite_case(c) {
            Some(false) => {
                lacking += 1;
                if !unsupported_ok(&r) {
                    bad.push(format!("{name}: a suite the guest lacks must fail with unsupported_suite, got {r:?}"));
                }
                continue;
            }
            Some(true) => pq += 1,
            None => {}
        }
        let ts = c["ok"].as_bool().unwrap();
        allowed += ts as usize;
        if r.is_ok() != ts || !reason_eq(c["reason"].as_str(), r.as_ref().err().map(|x| x.as_str())) {
            bad.push(format!("{name}: ts {:?} rust {:?}", c["reason"], r));
        }
        // boundRoot: where the TS reason is one of boundRoot's own, bound_root returns exactly it
        if let Some(tr) = c["reason"].as_str() {
            let br = tr.starts_with("session root: ") || BOUND_ROOT_REASONS.contains(&tr);
            if br && c["pcactn"].get("intent").is_some() {
                let b = bound_root(&c["pcactn"], ctx, now);
                if b.as_ref().err().map(|x| x.as_str()) != Some(tr) {
                    bad.push(format!("{name}: bound_root ts {tr:?} rust {:?}", b.map(|_| ())));
                }
            }
        }
        if ts && bound_root(&c["pcactn"], ctx, now).is_err() {
            bad.push(format!("{name}: an admitted case must have a bound root"));
        }
    }
    assert!(reported >= 95 && allowed >= 20 && pq >= 8 && lacking >= 1 && pipeline >= 1, "reported {reported} allowed {allowed} pq {pq} lacking {lacking} pipeline {pipeline}");
    report("steps", &bad, cases.len());
}
